module ActiveSupport;module Multibyte;module Unicode;extend self;UNICODE_VERSION=RbConfig::CONFIG["UNICODE_VERSION"];def decompose(type,codepoints)if type==:compatibility;codepoints.pack("U*").unicode_normalize(:nfkd).codepoints;else codepoints.pack("U*").unicode_normalize(:nfd).codepoints;end;end;def compose(codepoints)codepoints.pack("U*").unicode_normalize(:nfc).codepoints;end;def tidy_bytes(string,force=false)return string if string.empty?||string.ascii_only?;return recode_windows1252_chars(string) if force;string.scrub{|bad|recode_windows1252_chars(bad)};end;private;def recode_windows1252_chars(string)string.encode(Encoding::UTF_8,Encoding::Windows_1252,invalid: :replace,undef: :replace);end;end;end;end
